source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # The three-cell motif is the only contiguous run of non-background cells.
    candidates = []
    for r in range(h):
        for c in range(w - 2):
            coords = [(r, c + i) for i in range(3)]
            if all(grid[y][x] != background for y, x in coords):
                candidates.append((coords, [grid[y][x] for y, x in coords]))
    for r in range(h - 2):
        for c in range(w):
            coords = [(r + i, c) for i in range(3)]
            if all(grid[y][x] != background for y, x in coords):
                candidates.append((coords, [grid[y][x] for y, x in coords]))
    motif_coords, motif = candidates[0]
    motif_set = set(motif_coords)
    out = [row[:] for row in grid]

    # Replicate the motif at every isolated non-background point, aligning
    # its middle cell with that point.
    if motif_coords[0][0] == motif_coords[1][0]:
        dr, dc = 0, 1
    else:
        dr, dc = 1, 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in motif_set:
                continue
            for i, color in enumerate(motif):
                y, x = r + (i - 1) * dr, c + (i - 1) * dc
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = color
    return out
